bool pairSum(vector<int>& a, int t) {
    int l = 0, r = (int)a.size() - 1;
    while (l < r) {
        int s = a[l] + a[r];
        if (s == t) return true;
        if (s < t) l++; else r--;
    }
    return false;
}

// remove duplicates from sorted array, in place
int dedupe(vector<int>& a) {
    int w = 0;                 // next write position
    for (int i = 0; i < (int)a.size(); i++)
        if (w == 0 || a[i] != a[w - 1]) a[w++] = a[i];
    return w;                  // new length
}
